BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES
 ('f1140000-0000-0000-0000-000000000001','qa-atomic-business@example.test','{}'),
 ('f1140000-0000-0000-0000-000000000002','qa-atomic-business-other@example.test','{}');
CREATE FUNCTION pg_temp.business_cases() RETURNS SETOF text LANGUAGE plpgsql AS $$
DECLARE o jsonb; p jsonb; q jsonb; pi jsonb; updated jsonb; d uuid:=gen_random_uuid(); oi uuid:=gen_random_uuid(); a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); req uuid; bad_doc uuid; payload jsonb; inquiry uuid:=gen_random_uuid(); inquiry_item uuid:=gen_random_uuid();
BEGIN
 o:=public.romiku_save_document('order',d,0,gen_random_uuid(),'{"currency":"USD","notes":"financial","terms_snapshot":{"order_export":{"template_key":"order","seller":{"company_name":"Frozen seller"}}}}',jsonb_build_array(jsonb_build_object('id',oi,'sku','FRACTION','quantity',10,'unit_price',1.335)));
 RETURN NEXT is((o->'items'->0->>'amount')::numeric,13.35::numeric,'amount generated by server precision');
 RETURN NEXT ok(o->'header'->'terms_snapshot' ? 'order_export','order export snapshot preserved');
 RETURN NEXT ok(o->'header'->'production_defaults_snapshot' IS NOT NULL,'order production defaults preserved');
 RETURN NEXT throws_ok(format('select public.romiku_save_document(''order'',%L,%s,%L,''{"status":"voided"}'',null)',d,o->>'revision',gen_random_uuid()),'P4202','Use controlled order void','save cannot bypass controlled void');
 RETURN NEXT throws_ok(format('select public.romiku_save_document(''order'',%L,%s,%L,''{"void_reason":"forged"}'',null)',d,o->>'revision',gen_random_uuid()),'22023','Unsupported header field: void_reason','save cannot forge void audit fields');
 INSERT INTO public.romiku_payments(order_id,amount,kind) VALUES(d,1,'deposit');
 RETURN NEXT throws_ok(format('select public.romiku_save_document(''order'',%L,%s,%L,''{"currency":"EUR"}'',null)',d,o->>'revision',gen_random_uuid()),'23514','Order currency is immutable after payments exist','save preserves payment currency guard');
 payload:=jsonb_build_array(jsonb_build_object('id',a,'source_order_item_id',oi,'sku','SPLIT','quantity',5),jsonb_build_object('id',b,'order_id',d,'source_order_item_id',oi,'sku','SPLIT','quantity',5));
 p:=public.romiku_save_document('packing',gen_random_uuid(),0,gen_random_uuid(),jsonb_build_object('order_id',d),payload);
 RETURN NEXT is(jsonb_array_length(p->'items'),2,'same source supports multiple packing rows');
 payload:=jsonb_build_array(jsonb_build_object('id',a,'source_order_item_id',oi,'sku','SPLIT','quantity',8),jsonb_build_object('id',b,'order_id',d,'source_order_item_id',oi,'sku','SPLIT','quantity',2));
 p:=public.romiku_save_document('packing',(p->>'document_id')::uuid,(p->>'revision')::bigint,gen_random_uuid(),'{}',payload);
 RETURN NEXT is((SELECT sum((x->>'quantity')::numeric) FROM jsonb_array_elements(p->'items') x),10::numeric,'packing reductions precede increases');
 RETURN NEXT throws_ok(format('select public.romiku_save_document(''packing'',%L,0,%L,%L,''[{"sku":"BAD","quantity":1}]'')',gen_random_uuid(),gen_random_uuid(),jsonb_build_object('order_id',d)),'23514','Packing source must match header','order-backed packing cannot contain independent line');
 RETURN NEXT throws_ok(format('select public.romiku_save_document(''order'',%L,%s,%L,''{}'',''[]'')',d,o->>'revision',gen_random_uuid()),'23503',null,'referenced order item deletion rejected');
 RETURN NEXT is(public.romiku_document_snapshot('order',d),o,'referenced deletion fully rolls back');
 req:=gen_random_uuid();bad_doc:=gen_random_uuid();
 RETURN NEXT throws_ok(format('select public.romiku_save_document(''quote'',%L,0,%L,''{}'',''[{"sku":"BAD","quantity":0}]'')',bad_doc,req),'23514',null,'invalid create line rolls back');
 RETURN NEXT is(public.romiku_document_snapshot('quote',bad_doc),NULL::jsonb,'failed create leaves no header');
 RETURN NEXT is(public.romiku_document_save_result(req),NULL::jsonb,'failed create leaves no receipt');
 q:=public.romiku_save_document('quote',gen_random_uuid(),0,gen_random_uuid(),'{}','[{"sku":"Q","quantity":0.25,"unit_price":1.335}]');
 RETURN NEXT is((q->'items'->0->>'amount')::numeric,0.33::numeric,'fractional quantities retain financial rounding');
 pi:=public.romiku_create_document_from_source(gen_random_uuid(),'quote',(q->>'document_id')::uuid,'pi',null,(q->>'revision')::bigint);
 updated:=public.romiku_save_document('quote',(q->>'document_id')::uuid,(q->>'revision')::bigint,gen_random_uuid(),'{}',jsonb_build_array(jsonb_build_object('id',q->'items'->0->>'id','sku','Q EDIT','quantity',0.5,'unit_price',2)));
 RETURN NEXT is(updated->'items'->0->>'id',pi->'items'->0->>'source_quote_item_id','editing preserves referenced stable line ID');
 RETURN NEXT throws_ok(format('select public.romiku_create_document_from_source(%L,''quote'',%L,''order'',null,%s)',gen_random_uuid(),q->>'document_id',q->>'revision'),'PT409','STALE_REVISION','conversion rejects stale source revision');
 RETURN NEXT throws_ok(format('select public.romiku_save_document(''quote'',%L,0,%L,''{}'',%L)',gen_random_uuid(),gen_random_uuid(),jsonb_build_array(jsonb_build_object('id',q->'items'->0->>'id','sku','STOLEN','quantity',1))),'42501','Item belongs to another document','foreign parent item cannot be stolen');
 PERFORM set_config('romiku.atomic_save','true',true);
 RETURN NEXT throws_ok(format('update public.romiku_orders set notes=''spoof'' where id=%L',d),'42501','Use atomic document save','client-set GUC does not authorize direct writes');
 RETURN NEXT ok(NOT pg_has_role('authenticated','romiku_document_executor','MEMBER'),'authenticated is not executor role member');
 INSERT INTO public.romiku_website_inquiries(id,customer_name) VALUES(inquiry,'Atomic inquiry');
 INSERT INTO public.romiku_website_inquiry_items(id,inquiry_id,sku,quantity) VALUES(inquiry_item,inquiry,'INQ',3.25);
 req:=gen_random_uuid();
 q:=public.romiku_create_document_from_source(req,'website_inquiry',inquiry,'quote',ARRAY[inquiry_item],null);
 RETURN NEXT is((q->'items'->0->>'requested_quantity_snapshot')::numeric,3.25::numeric,'inquiry creation retains original requested quantity');
 RETURN NEXT is(public.romiku_create_document_from_source(req,'website_inquiry',inquiry,'quote',ARRAY[inquiry_item],null),q,'inquiry creation replay is durable');
END $$;
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claim.role='authenticated';
SET LOCAL request.jwt.claim.sub='f1140000-0000-0000-0000-000000000001';
SELECT * FROM pg_temp.business_cases();
SELECT public.romiku_save_document('quote','f1140000-0000-0000-0000-000000000010',0,'f1140000-0000-0000-0000-000000000011','{}',null) IS NOT NULL;
SET LOCAL request.jwt.claim.sub='f1140000-0000-0000-0000-000000000002';
SELECT is(public.romiku_document_save_result('f1140000-0000-0000-0000-000000000011'),NULL::jsonb,'another actor cannot read request receipt');
SELECT throws_ok('select * from public.romiku_document_save_requests','42501',null,'authenticated cannot read raw request journal');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT throws_ok('select public.romiku_document_snapshot(''quote'',gen_random_uuid())','42501',null,'anonymous cannot invoke document snapshot');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
